  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = overdueInvoices([issued.value], '2026-10-14');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('overdueInvoices returns DATE_INVALID for invalid asOf', () => {
  const r = overdueInvoices([], 'invalid-date');
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices with mix of overdue and current invoices', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);

  // inv1 due 2026-10-15, inv2 due 2026-10-24
  const r = overdueInvoices([issued1.value, issued2.value], '2026-10-20');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].dueDate, '2026-10-15');
});

test('overdueInvoices preserves all fields in result', () => {
  const invResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
    terms: 'NET30',
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const r = overdueInvoices([issued.value], '2026-11-05');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);

  const item = r.value[0];
  assert(item.number);
  assert.equal(item.customerId, 'C-002');
  assert.equal(item.dueDate, '2026-10-31');
  assert(typeof item.daysOverdue === 'number');
  assert(typeof item.due === 'number');
});

test('overdueInvoices handles partially paid invoice with remaining balance', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(invResult.ok, true);

  const issued = issueInvoice(invResult.value, []);
  assert.equal(issued.ok, true);

  const partial = recordPayment(issued.value, { amount: 30000, date: '2026-10-08' });
  assert.equal(partial.ok, true);

  const r = overdueInvoices([partial.value], '2026-10-20');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert(r.value[0].due > 0);
  assert(r.value[0].due < balanceDue(issued.value));
});

test('overdueInvoices returns empty array for empty input', () => {
  const r = overdueInvoices([], '2026-10-07');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 0);
});

test('overdueInvoices with invoices from multiple customers', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const inv2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);

  const r = overdueInvoices([issued1.value, issued2.value], '2026-10-16');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 2);
  assert(r.value.some(inv => inv.customerId === 'C-001'));
  assert(r.value.some(inv => inv.customerId === 'C-002'));
});

test('overdueInvoices calculates daysOverdue for different overdue amounts', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  assert.equal(inv1Result.ok, true);
  assert.equal(inv2Result.ok, true);

  const issued1 = issueInvoice(inv1Result.value, []);
  const issued2 = issueInvoice(inv2Result.value, ['INV-2026-0001']);

  // inv1 due 2026-09-15, inv2 due 2026-09-29
  const r = overdueInvoices([issued1.value, issued2.value], '2026-10-07');
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 2);

  // inv1 is 22 days overdue (2026-09-15 to 2026-10-07)
  // inv2 is 8 days overdue (2026-09-29 to 2026-10-07)
  assert.equal(r.value[0].daysOverdue, 22);
  assert.equal(r.value[1].daysOverdue, 8);
});

